// Testing OrderService.calculateTotal(Order order)

class OrderServiceTest {
    private OrderService service = new OrderService();

    @Test
    void calculateTotal_whenOrderHasNoItems_thenReturnsZero() {
        var order = new Order(List.of());
        var total = service.calculateTotal(order);
        assertEquals(0.0, total);
    }

    @Test
    void calculateTotal_whenOrderHasMultipleItems_thenSumsAllPrices() {
        var items = List.of(
            new Item("Laptop", 1000.0),
            new Item("Mouse", 25.0)
        );
        var order = new Order(items);
        var total = service.calculateTotal(order); // Should be 1025.0
        assertEquals(1025.0, total, 0.01);
    }

    @Test
    void calculateTotal_whenOrderIsNull_thenThrowsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class, 
            () -> service.calculateTotal(null));
    }
}

