package com.example.order;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class OrderServiceTest { // Note: package-private access is fine for tests
    private final OrderService service = new OrderService();

    @Test
    void calculateTotal_whenOrderHasItems_thenSumsCorrectly() {
        var items = List.of(new Item("Laptop", 1200.0));
        var order = new Order(items);
        assertEquals(1200.0, service.calculateTotal(order));
    }
}

class PaymentServiceTest {

    // BAD: Comment restates what the name already says
    @Test
    void processPayment_whenAmountIsValid_thenSucceeds() {
        // Test the happy path
        var payment = new Payment(100.0);
        var result = service.processPayment(payment);
        assertTrue(result.isSuccess());
    }

    // GOOD: Comment explains WHY this edge case matters
    @Test
    void processPayment_whenAmountIsOneCent_thenSucceeds() {
        // Regression test: Production bug #2847 failed for amounts < $0.10
        // due to rounding error in currency conversion. Must not regress.
        var payment = new Payment(0.01);
        var result = service.processPayment(payment);
        assertTrue(result.isSuccess());
    }

    @Test
    void calculateInterest_whenCompoundingDaily_thenMatchesFinancialRegulation() {
        // Per SEC Rule 17a-4: compound interest must use exact day count
        var account = new Account(1000.0);
        var interest = service.calculateInterest(account, 365);
        assertEquals(50.13, interest, 0.01); // Expected per regulatory formula
    }
}

