package com.example.order;

// Production class with package-private helper method
class OrderService {
    private OrderRepository repository;

    double calculateTotal(Order order) { // public method
        return order.items().stream()
            .mapToDouble(this::applyDiscount)
            .sum();
    }

    double applyDiscount(Item item) { // package-private: tests can access
        return item.price() * 0.9;
    }
}

// Test class in SAME package, different source root
class OrderServiceTest {
    @Test
    void applyDiscount_whenCalled_thenReducesPriceByTenPercent() {
        var service = new OrderService();
        var discounted = service.applyDiscount(new Item("Laptop", 1000.0));
        assertEquals(900.0, discounted); // Can access package-private method
    }
}
